import { spawnSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { CF_ENV, readEnvFile } from "./env.mjs";

const infraDir = join(dirname(fileURLToPath(import.meta.url)), "..", "infra");
const [command, ...args] = process.argv.slice(2);

if (command !== "plan" && command !== "apply") {
  console.error("usage: node npm-scripts/infra.mjs <plan|apply> [tofu args]");
  process.exit(2);
}

const fileEnv = readEnvFile(CF_ENV);
if (!fileEnv.CLOUDFLARE_API_TOKEN) {
  console.error(`${CF_ENV} does not set CLOUDFLARE_API_TOKEN`);
  process.exit(1);
}

const env = { ...process.env, CLOUDFLARE_API_TOKEN: fileEnv.CLOUDFLARE_API_TOKEN };
const tofu = (...tofuArgs) => {
  const run = spawnSync("tofu", tofuArgs, { cwd: infraDir, env, stdio: "inherit" });
  if (run.error) throw run.error;
  if (run.status !== 0) process.exit(run.status ?? 1);
};

tofu("init", "-input=false");
tofu(command, "-input=false", ...args);
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

if (process.env.WORKERS_CI !== "1") {
  console.error(
    "npm run deploy runs only inside Cloudflare Workers Builds; push to main to deploy",
  );
  process.exit(1);
}

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const state = JSON.parse(readFileSync(join(root, "infra", "terraform.tfstate"), "utf8"));
const output = (name) => {
  const value = state.outputs?.[name]?.value;
  if (!value) {
    console.error(`infra/terraform.tfstate has no ${name} output; run npm run infra:apply`);
    process.exit(1);
  }
  return value;
};

const run = spawnSync(
  "npx",
  [
    "wrangler",
    "deploy",
    "--var",
    `ACCESS_TEAM_DOMAIN:${output("access_team_domain")}`,
    "--var",
    `ACCESS_AUD:${output("access_aud")}`,
  ],
  { cwd: root, stdio: "inherit" },
);
if (run.error) throw run.error;
process.exit(run.status ?? 1);
